<?php
require __DIR__.'/ui.php';role(['admin','gerente','producao']);$p=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);$d=[trim($_POST['name']),trim($_POST['category']),trim($_POST['sku']),floatval($_POST['cost']),floatval($_POST['price']),floatval($_POST['stock']),floatval($_POST['min_stock']),trim($_POST['unit']),intval($_POST['shelf_life_days']),floatval($_POST['labor_cost']),floatval($_POST['packaging_cost']),floatval($_POST['loss_pct']),floatval($_POST['desired_margin']),trim($_POST['image_url']),trim($_POST['description'])];if($id){$p->prepare("UPDATE products SET name=?,category=?,sku=?,cost=?,price=?,stock=?,min_stock=?,unit=?,shelf_life_days=?,labor_cost=?,packaging_cost=?,loss_pct=?,desired_margin=?,image_url=?,description=? WHERE id=?")->execute([...$d,$id]);}else{$p->prepare("INSERT INTO products(name,category,sku,cost,price,stock,min_stock,unit,shelf_life_days,labor_cost,packaging_cost,loss_pct,desired_margin,image_url,description)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)")->execute($d);}go('products.php');}
$edit=null;if(isset($_GET['edit'])){$s=$p->prepare("SELECT * FROM products WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$p->query("SELECT * FROM products ORDER BY name")->fetchAll();page_head('Produtos');?>
<div class="grid g2"><div class="card"><h2><?=$edit?'Editar':'Novo'?> produto</h2><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$edit['id']??''?>"><div class="grid g3"><div><label>Nome</label><input name="name" required value="<?=e($edit['name']??'')?>"></div><div><label>Categoria</label><input name="category" value="<?=e($edit['category']??'')?>"></div><div><label>SKU</label><input name="sku" value="<?=e($edit['sku']??'')?>"></div><div><label>Custo base</label><input type="number" step=".01" name="cost" value="<?=$edit['cost']??0?>"></div><div><label>Preço venda</label><input type="number" step=".01" name="price" value="<?=$edit['price']??0?>"></div><div><label>Estoque</label><input type="number" step=".01" name="stock" value="<?=$edit['stock']??0?>"></div><div><label>Estoque mínimo</label><input type="number" step=".01" name="min_stock" value="<?=$edit['min_stock']??1?>"></div><div><label>Unidade</label><input name="unit" value="<?=e($edit['unit']??'un')?>"></div><div><label>Validade (dias)</label><input type="number" name="shelf_life_days" value="<?=$edit['shelf_life_days']??0?>"></div><div><label>Mão de obra</label><input type="number" step=".01" name="labor_cost" value="<?=$edit['labor_cost']??0?>"></div><div><label>Embalagem</label><input type="number" step=".01" name="packaging_cost" value="<?=$edit['packaging_cost']??0?>"></div><div><label>Perdas %</label><input type="number" step=".1" name="loss_pct" value="<?=$edit['loss_pct']??5?>"></div><div><label>Margem desejada %</label><input type="number" step=".1" name="desired_margin" value="<?=$edit['desired_margin']??50?>"></div></div><label>URL da imagem</label><input name="image_url" value="<?=e($edit['image_url']??'')?>"><label>Descrição</label><textarea name="description"><?=e($edit['description']??'')?></textarea><button class="primary">Salvar</button></form></div>
<div class="card"><h2>Resumo</h2><div class="grid g3"><div class="kpi"><span>Produtos</span><strong><?=count($rows)?></strong></div><div class="kpi"><span>Críticos</span><strong><?=count(array_filter($rows,fn($x)=>$x['stock']<=$x['min_stock']))?></strong></div><div class="kpi"><span>Valor em estoque</span><strong><?=money(array_sum(array_map(fn($x)=>$x['cost']*$x['stock'],$rows)))?></strong></div></div></div></div>
<div class="card"><div class="table"><table><tr><th>Produto</th><th>Custo</th><th>Venda</th><th>Estoque</th><th>Margem</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=money($r['cost'])?></td><td><?=money($r['price'])?></td><td><?=$r['stock']?></td><td><?=$r['desired_margin']?>%</td><td><a class="btn" href="?edit=<?=$r['id']?>">Editar</a></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>